import 'package:modbus_client/modbus_client.dart';
import 'package:modbus_client_serial/modbus_client_serial.dart';

void main() async {
  var temp = ModbusInt16Register(
      name: "BatteryTemperature",
      type: ModbusElementType.inputRegister,
      address: 22,
      uom: "°C",
      multiplier: 0.1,
      onUpdate: (self) => print(self));
  var client = ModbusClientSerialRtu(portName: "COM1", unitId: 1);
  await client.send(temp.getReadRequest());
  client.disconnect();
}
